INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (60002403, 'A woman is thrilled to find out she''s pregnant. But as her belly grows, the more certain she becomes that her unborn child is in serious danger.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (17236920, 'A law student befriends and "befoes" a fellow gambling addict and a club owner, and tensions run high when they must come up with $15k in just 5 days.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (923574, 'During a visit to the Bronx to help out at his uncle''s store, a cheerful martial arts expert springs into action when a gang terrorizes the shop.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81152930, 'Fleeing the family business and an arranged marriage, Santa’s daughter chooses a magical adventure of her own: College.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (973861, 'A man returns home after being released from a psychiatric hospital, where he''d been confined since age 12 for murdering his mother and her lover.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70058796, 'In 1950s Harlem, three singing sisters hit the big time and end up losing one another in this musical melodrama inspired by the Supremes.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70047101, 'The seemingly invincible Spider-Man goes up against an all-new crop of villains in the third installment of the blockbuster adventure series.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81189396, 'In this epic documentary, last-surviving veterans trace the history of a legendary fighter aircraft that dominated the air during the Battle of Britain.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70093991, 'Brennan and Dale might be grown men, but that doesn''t stop a childish sibling rivalry from erupting after Brennan''s mom marries Dale''s dad.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (60033247, 'To get away from the thug life, cocaine dealer Youngblood Priest puts together one last deal that will net him enough money to start over.');
