INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (1178866, 'Nicholas receives an unusual birthday present from his brother, Conrad – a gift certificate to play a unique kind of game formulated by "CRS."');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (60033312, 'In World War II, a battalion goes on a daring rescue mission to liberate the Americans and Filipinos who''ve been captured by the Japanese.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81030409, 'The de la Mora siblings publicly mourn the death of their mother amid multiple surprises and mishaps at Virginia''s funeral.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80182016, 'Wayward Prince Hal must turn from carouser to warrior king as he faces hostilities from inside and outside the castle walls in the battle for England.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (684847, 'Private eye Joe Hallenbeck is forced to team up with a disgraced quarterback to uncover a conspiracy by a politician and a football team owner.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81150305, 'A gravity-defying boy raised in seclusion matures into an extraordinary man – and an international celebrity – who longs for human connection.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (20557937, 'A computer hacker learns that what most people perceive as reality is actually a simulation created by machines, and joins a rebellion to break free.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (60027695, 'The crew must protect Zion, the last outpost still under human control, after it is pinpointed by the machines responsible for the Matrix.');
