INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81170692, 'While carrying out prison sentences, five notorious thieves in Mexico City share their principles, preferred methods and respect for the craft.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (848915, 'When law student Darby Shaw theorizes about the assassinations of two Supreme Court justices, she is put in danger and turns to a reporter for help.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (60022980, 'After a government spy is hospitalized, New York City cab driver Jimmy unwillingly takes over the spy''s role – with the aid of a computerized tuxedo.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (60003961, 'The spotlight shines on iconic jazz pianist and composer Thelonious Monk in this 1988 documentary featuring vintage performance clips and interviews.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81035120, 'It''s Grabbleapple harvest season in the Rainbow Kingdom ... but Glummy Glooma doesn''t want autumn to come. Can True and her friends save the festival?');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70060005, 'Moments after he arrives in Spain for an antiterrorism summit, U.S. President Ashton is shot.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70266992, 'José Olaya, a Spanish miner, emigrates to Argentina in 1934, while his son, an architect, moves to Spain after Argentina''s economic collapse in 2001.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80218819, 'A mysterious classmate leads four idealistic teens in a revolt against a rising tide of nationalistic fervor, but their movement takes a dark turn.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70084791, 'When a spoiled girl pushes her father too far with her spending and outlandish behavior, he ships the Malibu princess off to a strict boarding school.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81170694, 'This introspective rockumentary follows the career triumphs and intimate moments of legendary Mexican band Zoé as they embark on a global tour.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70123542, 'Looking to survive in a world taken over by zombies, a dorky college student teams with an urban roughneck and a pair of grifter sisters.');
