INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81034099, 'Alex Trebek hosts one of TV''s longest-running game shows, where a trio of players buzz in with their knowledge of history, arts, pop culture and more.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81110394, 'In an ancient sport traditionally reserved for men, 20-year-old female sumo prodigy Hiyori attempts to revolutionize Japan’s national pastime.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81197399, 'Six hopeful friends journey into adulthood to create the moments that pull them together, draw them apart and make them fall in love.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81185502, 'A shy college student with a knack for drawing develops a crush on a musically gifted classmate and embarks on a journey of self-discovery.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81123469, 'After a star player dies during football practice, his coach’s career and reputation are on the line as he refuses to quit his win-at-all-costs style.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80081372, 'Based on the memoirs of author Amos Oz, this poetic drama shares his family''s tale of suffering and survival in the early years of independent Israel.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81136744, 'A group of friends making a web series about their hometown realize it isn’t as boring as they thought when their neighbors start behaving strangely.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70300800, 'Meet the most beloved sitcom horse of the ''90s, 20 years later. He’s a curmudgeon with a heart of...not quite gold...but something like gold. Copper?');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80221210, 'An honest lawyer reaches a moral crossroads after the cops force her to inform on her incarcerated brother, the leader of a rising criminal faction.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81192130, 'This educational series for tiny tots features a toe-tapping spin on nursery rhymes with upbeat tunes and a diverse set of easy-to-follow lessons.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81132444, 'Secrets bubble to the surface after a sensual encounter and an unforeseen crime entangle two friends and a woman caught between them.');
