INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80095435, 'When teen siblings Hayley and Alex enter an elite boarding school, they find rivalry, romance and a mystery related to the recent loss of their mom.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81078456, 'The extraordinary life of beloved acting teacher and theatre producer Wynn Handman is recalled in this portrait of a provocative, innovative artist.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81105406, 'This dramatization tells the story of Argentine boxing champion Carlos Monzón, as well as the investigation into the death of his wife Alicia Muñiz.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81121023, '"King of Bollywood" Shah Rukh Khan opens up about his rise to fame, his family and his billions of fans as he and Dave meet up in Mumbai and New York.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81061828, 'On this fun and funny competition show, home bakers talented in catastrophe struggle to re-create dessert masterpieces and win a 5,000 euro prize.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81062582, 'On this competition show, novice bakers try to avoid a fiasco while duplicating stunning sweets. At stake are a trophy and 5,000 euros.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81017316, 'Monstrous frights meet hilarious reveals on this hidden-camera prank show as real people become the stars of their own full-blown horror movie.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81018455, 'After a mysterious woman saves her daughter from a deadly snakebite, a single mother must repay the debt by killing a stranger before sundown.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81110383, 'Pressured to marry a nice Orthodox Jewish woman, Motti is thrown for a loop when he falls for classmate Laura, who his mother will never approve of.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80201680, 'Acting coach Sandy Kominsky and best friend Norman Newlander keep each other laughing as they navigate the ups and downs of getting older.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81200228, 'In a magical world of inter-clan rivalry, two soulmates face treacherous schemes and uncover a dark mystery linked to a tragic event in the past.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81011059, 'The world is a mystery to little Booba. But he approaches the curiosities around him with wonder, finding adventure in his everyday surroundings.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80197462, 'Living his best life in post-apocalyptic LA, a slacker strives to find the girl of his dreams while outwitting mindless ghouls and cliquish gangs.');
