INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81075461, 'A wedding in a Malaysian village leaves out one guest: a scorned vampire ghost bent on settling a secret score with the groom and anyone in her way.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80017261, 'An ex-con is just getting his life back on track when his older brother is released from prison and drags him into the underworld for one final heist.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81038022, 'Chef David Chang takes his insatiable curiosity about food, culture and identity on the road, in the convivial company of fun-loving celebrity guests.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80186796, 'From ruffling their majestic feathers to nailing im-peck-able courtship routines, birds in paradise flaunt their best moves in hopes of landing a mate.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81071891, 'In this spin-off, a martial arts expert once defeated by Ip Man is forced to abandon his reclusive lifestyle to combat a rising Chinese triad.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70295169, 'A hired gun has second thoughts when he''s contracted to kill a teenage girl whose father''s shady business dealings put her life in danger.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80039050, 'After the passing of her dog, a long-widowed senior citizen is in need of companionship. Two very different possibilities present themselves.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81027753, 'Jenny Slate''s first stand-up special is a mix of stage time, funny stories about adulthood and conversations with family in her childhood home.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (15815343, 'When some friends visit a vandalized graveyard, they come upon a chainsaw-wielding maniac, and it''s a fight to the bloody death between good and evil.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70295176, 'When a bike messenger falls into debt with organized criminals, a sexy woman draws him into her high-stakes world of parkour, teaching him new skills.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81043190, 'A man cured of leprosy and a young orphan leave their colony for the first time to travel across Egypt, hoping to find the families they lost.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80091310, 'A sketchy arms transaction in a deserted warehouse turns into a free-for-all when the two sides engage in a take-no-prisoners shootout.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80995687, 'Kaal is back – bigger and badder than ever! Can Little Singham fight the battle of a lifetime to stop the demon’s plans to wreak havoc on earth?');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (60001650, 'A streetwise cop teams with a veteran government agent to work for a super-secret, extremely dapper team that monitors extraterrestrials on Earth.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81172848, 'Two fierce mothers become rivals when a school contest forces their kids, both model students, to compete against one another to be the best in class.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81034575, 'For the crew trapped aboard a sunken Russian submarine the deadliest threat is the bureaucracy on land. Based on a true story.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81172729, 'After his girlfriend wins the Miss Nigeria pageant, a young man faces unexpected competition of his own when he joins her on a campaign in South Africa.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81172895, 'Heroic health workers fight to contain an Ebola outbreak when a patient arrives in Lagos with symptoms of the deadly virus. Based on a true story.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80211634, 'Fed up with their families and classmates, two teen girls from a wealthy part of Rome are drawn to the city''s underworld and start leading double lives.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80206910, 'With his desperate parents in tow, an 11-year-old boy with a debilitating illness checks into an isolated clinic to undergo experimental therapy.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81172905, 'A teacher turns to a dubious man to raise money for her daughter''s life-saving surgery, a crisis that is unexpectedly catapulted to a national stage.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80217627, 'Aspiring interior designers transform a variety of spaces from dowdy to delightful as they vie for a life-changing contract with a top London hotel.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80176872, 'Twinkle, Mia, Jacus and the rest of the Nursery Rhyme Friends perform catchy tunes for the little ones.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80178724, 'Burned out on life, Miles undergoes a strange procedure at a strip mall spa – and wakes to find he''s been replaced by a better version of himself.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81132442, 'When a group of people meets at the same party, they form four different relationships, each experiencing similar phases of love.');
