INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81092909, 'Awkward 16-year-old Andrei is infatuated with his alluring but aloof schoolmate Ramona – until he meets stunning hotel clerk Anemona while on vacation.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81070008, 'A gripping profile of Ben Ferencz, the last surviving lead prosecutor at the Nuremberg trials whose lifelong desire for justice altered the rule of law.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70098605, 'Two detectives investigate a rash of vigilante killings linked to an old case, suggesting they might have put an innocent man behind bars.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81077539, 'An aging blues guitarist and a grad student form an unlikely duo while busking on the street corners of 1980s Harlem.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (20129240, 'When the Commando Elite, a group of toy action figures, are released before they''ve been tested, they attack the children playing with them.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70108017, 'A couple must decide whether to push a button that will net them a million dollars but that will also cause the death of a complete stranger.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70011219, 'In 1870, a disfigured recluse roams beneath a Parisian opera house and takes under his wing a young soprano, with whom a love triangle develops.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80097424, 'After years of limited contact with Earth, an inquisitive teen who lives on Mars makes an interplanetary trek to discover his own origins.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80203143, 'A hypochondriac confronts his fear of death when a terminally ill teen girl enlists him to help her complete her bucket list.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81068732, 'Raised in a boxing gym, two orphaned brothers become highly skilled martial artists and must combat threats in the streets and the ring.');
