INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80202874, 'Reunited after 15 years, famous chef Sasha and hometown musician Marcus feel the old sparks of attraction but struggle to adapt to each other''s worlds.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80221787, 'This sprawling crime drama follows the true story of the Rizzuto family and its associates, who presided over organized crime in Montreal for decades.');
