INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70045644, 'Star athlete Rohan has his eye on a beautiful art student. But when his best friend Simran experiences a crisis, he drops everything to help her.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70025612, 'True love is put to the test when another woman comes between a pair of star-crossed young lovers in this thriller.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80237006, 'When his mother suffers a traumatic incident, a boy from the Mumbai slums treks to Delhi to deliver his written plea for justice to the Prime Minister.');
