INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80160033, 'An orphan girl taught magic by her sick grandma must find work in seedy Bangkok, where unsavory characters run afoul of her increasingly dark powers.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81111849, 'After a five-year suspension, a once-legendary race car driver decides to get back in the game against a new generation of opponents.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80083930, 'A couple out to have a sensuous weekend at a house outside of Mumbai finds it rigged with surveillance cameras and occupied by an evil entity.');
