INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81010699, 'A minister who researches religious cults turns to his Buddhist monk friend for help investigating a new group with mysterious origins.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70299863, 'Confronted with the potential end of their marriage, Ethan and Sophie take off for a weekend together, hoping to negotiate their future.');
