INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81077874, 'New Zealand film archivist Heperi Mita traces the cinematic legacy of his mother and trailblazing Maori filmmaker Merata Mita.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81098013, 'After surviving a near-fatal injury on the job, a cop sets out to investigate a conspiracy involving the top brass of the police department.');
