INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81092779, 'Finally released after being trapped in an ancient book for centuries, a wicked warrior sets out to conquer Dholakpur – but not if Bheem can help it!');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81092776, 'Bheem and King Indraverma travel to Rome for a trading venture, but when the king of a neighboring land attacks, can Bheem’s wile and wit save the day?');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81092778, 'Trolls kidnap the king''s daughters and overtake the kingdom of Messina. Can Bheem track them down and bring the princesses home?');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80095699, 'This eclectic, star-studded anthology follows diverse Chicagoans fumbling through the modern maze of love, sex, technology and culture.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80216541, 'After her partner cheats on her, an architect returns to her hometown to reassess her life with the help of her eccentric family. Based on the novel.');
