INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80987113, 'A princess descended from a ruined noble family disguises herself as the woman who saved her life and embarks on a mission to avenge her loved ones.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80197989, 'When everyone else mysteriously vanishes from their wealthy town, the teen residents of West Ham must forge their own society to survive.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80194950, 'When longtime friends meet up for a wine-soaked birthday getaway in Napa Valley, their perfectly planned weekend turns messier by the minute.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81035836, 'Learning he is the grandson of a famous knight, a young man hilariously fights a rival gang to win over the most beautiful woman in the tribe.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81044103, 'A comedy writer for David Letterman unearths a hidden world of hilariously bizarre musicals, which turns into a toe-tapping obsession.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81072917, 'When a zealous gang leader plans to take out a friend-turned-rival for control of his turf, internal tensions complicate the battle to be the boss.');
