INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81035857, 'A taxi driver longs to be a pop singer, but the road to stardom is wrought with competition and struggle until he befriends a helpful belly dancer.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80180684, 'A high-achieving 11-year-old student embarks on a journey of self-discovery at a school on a nearby island as he grapples with tensions at home.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80180681, 'When a busy mother and father realize they need help with their two young children, they hire a series of maids, often with humorous results.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80180710, 'Two female friends, each with confidence issues, help each other search for true love and deal with their romantic rivals.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80180545, 'Dedicated engineering student Iris succumbs to love and marries, but fate holds both tragedies and triumphs for her personal and professional life.');
