INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80218099, 'A game of "Truth or Dare" among college friends on spring break turns deadly when a demon seems determined to use it to kill them all.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80218973, 'An ex-racecar driver is sent to a barbaric prison where, to get pardoned, he must defeat the inmate known as Frankenstein in a lethal "Death Race."');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80235999, 'In a madcap stage play from Monty Python icon Eric Idle, comic greats perform the decline and fall of the British Empire ... as told through a piano.');
