INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80137461, 'Four brothers learn that they have inherited ancestral land, but must fight to claim it when a greedy feudal lord threatens to take it over.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81012857, 'Beatrix can''t wait to be inducted as a witch, but an unfortunate incident threatens to take her pending title away if she doesn''t act fast.');
