INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (81024712, 'An ambitious young athlete endeavors to revive his floundering running career after falling prey to negative influences.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70112494, 'Three cops find themselves hurtling toward the same crime scene on one fatal night in this tense, edge-of your-seat thriller.');
