INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80023689, 'A coder at a tech company wins a week-long retreat at the compound of his company''s CEO, where he''s tasked with testing a new artificial intelligence.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70278930, 'In this kung fu tale set in Beijing, a young man armed with incomparable martial arts skills gets embroiled in the world of underground fight clubs.');
