INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80994573, 'When a late poet leaves behind his property to a young man, the man''s brother suspects the poet may have been more than just a family friend.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70057519, 'An esteemed young poetry teacher at a Catholic boarding school risks everything when she engages in a feverish affair with a female student.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80994425, 'The relationship between a journalist and a lawyer she meets while investigating a story grows complicated as she uncovers layers of deception.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (60029032, 'When Melvin and his friends gather for dinner, their casual conversation takes a sharp turn as they begin to disclose raw truths about themselves.');
