INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70142386, 'Follow the quirky agents of the NCIS – the Naval Criminal Investigative Service – as they track down terrorists and other high-profile criminals.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80996343, 'In a battle of the bands, a percussions student and her musical kindred spirits set out to prove the merits of Chinese folk against the Western canon.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80994419, 'A face painter for Theyyam rituals who is himself disfigured conceals his guilt over the fact that he performs abortions as a medical practitioner.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80994426, 'As the parents of three unmarried daughters, a humble cook and his wife contend with the challenges of matchmaking and social expectations.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80994574, 'A wealthy businessman''s miserly habits cause no small amount of stress and embarrassment to his family, particularly his daughter.');
