INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80163156, 'Jerry Seinfeld returns to the club that gave him his start in the 1970s, mixing iconic jokes with stories from his childhood and early days in comedy.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80176878, 'Faced with few clues and an increasingly panicked public, the FBI calls on a new kind of profiler to help track down the infamous Unabomber.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80192815, 'While visiting Ken and exploring a coral reef, Barbie and her sisters make an amazing discovery and meet a mysterious new friend.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80136785, 'Teenage Xue Ming was forced to marry the man who raped her. Years after abandoning her young sons to find a better life, can she escape the guilt?');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80136784, 'An insurance adjuster investigates cases of possible fraud while hiding a romance with a colleague, unaware that someone he trusts is toying with him.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80135278, 'The artistic pursuits of two childhood friends, an aspiring singer and a talented dancer, lead them to four other 20-somethings in a drumming group.');
