INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80165072, 'Crime journalist Donal MacIntyre reveals how deadly the internet can be as he dissects the technological methods behind heinous acts.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80067522, 'A 5-year-old girl embarks on a harrowing quest for survival amid the sudden rise and terrifying reign of the Khmer Rouge in Cambodia.');
