INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80198046, 'An international group of filmmakers sets out on a mission to get up close and personal with a family of elusive snow leopards.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80118289, 'A Melbourne obstetrician in her thirties struggles with the increasingly chaotic family, romantic and professional aspects of her life in this drama.');
