INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80158670, 'Ventriloquist Jeff Dunham brings his rude and slightly demented posse of puppets to Ireland for a gleeful skewering of family and politics.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80162143, 'After a teenager goes to live with his father in abandoned public housing, he hears strange noises and decides to investigate with his new friend.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80125979, 'When nerdy high schooler Dani finally attracts the interest of her longtime crush, she lands in the cross hairs of his ex, a social media celebrity.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80163890, 'A young journalist is forced into a life of crime to save his father and family in this series based on the novel by Miguel Sáez Carral.');
