INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80079255, 'Mafia activity in Naples is at the center of this series, which focuses on internal struggles that follow after the head of a family is imprisoned.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80163295, 'Sparks of both passion and contempt fly when a self-sufficient architect is forced to work with a snobbish industrialist.');
