INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80138469, 'During World War II, a Chinese railroad worker leads a group of brave resistance fighters against the forces of Japanese occupation.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80049903, 'Half dinosaur, half construction truck, full-on fun! Watch giant Ty Rux, his little buddy Revvit and the crew come face-to-face with evil D-Structs.');
