INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80175913, 'When his wife is convicted of murder, a horrified family man races to prove her innocence while a dogged investigator sets out to uncover the truth.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80182274, 'A blend of cultural nuance and mesmerizing techniques adds flavor to this globe-hopping celebration of cooking, tradition and community.');
