INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70209163, 'When he''s seen dispatching a rude opposing hockey player in the stands, Doug Glatt is hired by a rival team ... for his fighting skills.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80170687, 'Five beautiful but mysterious women move in with unsuccessful novelist Shin, who manages their odd household in exchange for a tidy monthly sum.');
