INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80011539, 'Bob the Tomato, Larry the Cucumber and their Veggie pals venture beyond the kitchen counter in these playful adventures with Christian themes.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70197042, 'Ex-CIA agent John Reese and enigmatic billionaire Mr. Finch use software that can predict future events to prevent violent crimes before they occur.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80119815, 'Two determined Athenian attorneys spearhead a lawsuit against the British Museum for the return of the Parthenon Marbles to Greece.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70242079, 'A homicide detective and a veteran who has been turned into a beast by a military experiment gone awry become allies after they meet by chance.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80131281, 'Charismatic comedy pals Karol Modzelewski and Łukasz "Lotek" Lodkowski bring their mischievous brand of humor to Warsaw''s Klub Hybrydy.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80131374, 'Polish comedians Rafał Pacześ and Katarzyna Piasecka hit the stage at Warsaw''s Klub Hybrydy for a night of funny anecdotes and sly jokes.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80131436, 'Comedians Mariusz Kałamaga, Karol Kopiec and Wiolka Walaszczyk deliver an eclectic and energetic stand-up show at Klub Hybrydy in Warsaw.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80131376, 'Young Polish comedians Rafał Banaś and Michał Leja present a high-energy stand-up show at Warsaw''s Klub Hybrydy.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80131435, '"Recipe for Life" star Rafał Rutkowski and Comedy Lab''s Olka Szczęśniak serve up humorous impressions and wry wit at Warsaw''s Klub Hybrydy.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80131375, 'Writer, actor and satirist Tomasz Jachimek teams up with comedian Jacek Stramik for a night of subversive stand-up at Klub Hybrydy in Warsaw.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70295760, 'The classic tales of Dracula, Frankenstein, Dorian Gray and more are woven together in this horror series set on the dark streets of Victorian London.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80092885, 'Trapped in a lab and stuck in a time loop, a disoriented couple fends off masked raiders while harboring a new energy source that could save humanity.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80108371, 'Donning his signature suit and fedora, the dapper comic offers a unique spin on getting old, the presidential election and "Honky Tonk Badonkadonk."');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70129452, 'Emmy-winning comedy writer Louis C.K. brings his caustic wit to Milwaukee, offering up his unique and uncensored take on sex, parenting and more.');
