INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80126566, 'Part live-action and part animation, this visually inventive series offers striking portrayals of some of the unsung heroes of World War II.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80106307, 'Witness the wrenching emotions that accompany end-of-life decisions as doctors, patients and families in a hospital ICU face harrowing choices.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80117401, 'Jandino Asporaat riffs on the challenges of raising kids and serenades the audience with a rousing rendition of "Sex on Fire" in his comedy show.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80024113, 'In a time of legend, Galavant the knight embarks on a quest to save his fair lady and become a hero in this tongue-in-cheek musical comedy.');
