INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80128096, 'Sample the bold new flavors of France with chefs who are pushing the boundaries of fine dining and reinventing a rich culinary tradition.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80057610, 'In a tale of bravery and heroism, fearless frogs go to war against the sinister scorpions and spiders that have teamed up to conquer the amphibians.');
