INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70229514, 'While the housemates in the Big Brother house remain oblivious, fast-moving hordes of the undead decimate the studio compound.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80114155, 'A young mother embarks on a desperate quest for freedom when she kidnaps her 10-year-old daughter to save her from a tribal marriage.');
