INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70303289, 'Beautiful housewife Xie An Zhen seems to be living the perfect life but finds her world crumbling after learning that her husband is cheating on her.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80111614, 'Libertine He-jie finds himself torn between the lovely Amanda and fiery Xiao-qian. But now he faces a new problem: arrogant rival suitor Cheng-en.');
