INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80097431, 'Grammy-nominated comedians Jeff Foxworthy and Larry the Cable Guy bring their distinctive brand of humor to a packed crowd in Minneapolis.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80057691, 'The lives of a budding DJ, his loyal pal, a hopeless romantic, a jaded has-been and a troubled couple intersect at an electronic dance music festival.');
