INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70044256, 'Comedian Jim Gaffigan cuts loose on a variety of topics, including Hot Pockets, holidays, Catholicism and his favorite activity: doing nothing.');
