INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70237054, 'Funnyman Jim Gaffigan offers up his unique take on everything from Disney World to overweight whales in this live show from Washington, D.C.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70301469, 'Comic Jim Gaffigan delivers his sardonic take on topics like eating, exercise, weddings and his five kids in this live stand-up special.');
