INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80022632, 'After a mysterious disease kills every resident over 22 years old, survivors of a town must fend for themselves when the government quarantines them.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80104950, 'As he grapples with a life-threatening illness, a police investigator tracks the explosion of a new synthetic drug on the streets of Paris.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80114498, 'Featuring interviews with participants on all sides, this documentary questions Norway and the West''s protracted military involvement in Afghanistan.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80036981, 'A middle-aged adman is shaken up by his new boss, a 25-year-old who advises him to "rebrand" himself. Is it possible, or is this as good as he''ll get?');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80106979, 'Returning for a second Netflix comedy special, Jim Jefferies unleashes his famously ferocious black humor to a packed house in Nashville, Tennessee.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80053140, 'Already coping with a bully, a mercurial older brother and summer school, 15-year-old Jack is saddled with his young cousin for an eventful weekend.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80065182, 'A failed musician unleashes his brain''s full powers with a new drug and is hired to solve the FBI''s hardest cases in this show based on the 2011 film.');
