INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80005588, 'This documentary series follows wild creatures in their native habitats as they navigate the perilous journey from birth to adulthood and beyond.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80076698, 'Martial arts master Ip springs into action when his son''s school is threatened by a shady American, then defends his status as wing chun champion.');
