INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80058427, 'Five best friends face adventures side by side in their hometown. Zany antics, love and missteps are better with friends!');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80106124, 'Combining his trademark wit and self-deprecating humor with original music, Bo Burnham offers up his unique twist on life in this stand-up special.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80095626, 'A dramatic series about friendship and conflict between two comedians who search for meaning in life and comedy. Based on the prize-winning book.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80104022, 'This series examines the nature of cuteness and how adorability helps some animal species to survive and thrive in a variety of environments.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80103006, 'Get up close and personal with avalanches, fiery volcanoes and other natural cataclysms, and learn why some choose to live in their destructive paths.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80104041, 'This film chronicles the health and social problems that African albinos face and details the fight waged on their behalf by advocacy groups in Spain.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80097532, '"The Joy of Painting" host Bob Ross brings his signature wet-on-wet style to a bevy of bucolic landscape paintings celebrating the beauty of nature.');
