INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80028208, 'Comedian Tig Notaro announced her cancer diagnosis at what became a legendary stand-up set in 2012. Follow her search for humor amid devastating news.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80025553, 'Three high school friends who turn into mermaids whenever they touch water have undersea adventures while keeping their new life a secret.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80014996, 'A medical apprentice in 11th-century Persia disguises himself as a Jew to study at a school that does not admit Christians.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70306646, 'When a cash-strapped videographer takes a job in a remote mountain town, he finds that the client has some unsettling ideas in mind.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80044731, 'Filmed in his hometown of Atlanta, Chris Tucker showcases his stand-up comedic chops as he shares his experiences from childhood to the big time.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80004286, 'When Clawdeen gets a chance to study with a top fashion designer, she and her pals hop on a plane to Scaris, France, the city where screams come true.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80027772, 'A boy and his best friend – his newly detached butt – embark on wacky adventures in a world where humans and their butts live side by side.');
