INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70308063, 'Using never-before-heard recordings, rare archival footage and her best-known songs, this is the story of legendary singer and activist Nina Simone.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80038420, 'In order to keep her job at a biomedical engineering firm that prizes youth, a middle-aged woman must submit to a drastic experimental procedure.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70177040, 'Follow the adventures of superspy Danger Mouse and his bumbling sidekick, Penfold, as they jet around the world foiling their enemies'' evil plots.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70155579, 'Crafty 11-year-old Johnny Test and his genetically modified talking dog go on high-octane adventures to save his family (and the world) from disaster.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80032640, 'After accepting a colossal bribe, a powerful TV conglomerate gins up fake news stories to enhance the image of a notoriously corrupt politician.');
