INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80038162, 'This 2015 Sundance Film Festival breakout documentary from producer Rashida Jones spotlights the "amateur" porn industry and the women it exploits.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80038335, 'Jen Kirkman delivers some sharp, hilarious truths about divorce, kids, sex and turning 40 in this Netflix original comedy special.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80020540, 'After turning his veggies into green energy, Richie Rich earns a trillion dollars overnight and a new life filled with nonstop fun and adventure.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80011852, 'This chronicle of Bob Weir highlights his brotherhood with Jerry Garcia and his success as a member of one of the world''s most influential bands.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80028529, 'When suspicious scout fairies scheme to capture the fearsome-looking NeverBeast, Tinker Bell and Fawn set out to save the wondrous creature.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80028359, 'A spunky terrier named Russell with serious wrestling chops becomes a sports phenomenon with the help of his coach, a monkey named Hunk.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70225722, 'Discover the glorious variety of life on Earth and the spectacular and extraordinary tactics animals and plants have developed to stay alive.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70266023, 'Members of the BBC''s "Life" production crew go behind the scenes to explain just what it took to capture key sequences of the program.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80045629, 'Look behind the scenes of this wildlife documentary series that examines how animals around the world adapt to chaotic natural phenomena.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70219642, 'This landmark series transports nature lovers from the Himalayan Mountains to the depths of the ocean and everywhere in between.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80029368, 'Stand-up comedian Chris D''Elia covers everything from how to improve the NFL to why dating is evil and that babies should grow up before they''re born.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70283263, 'The passionate love between an alien boy and a human girl grows more and more dangerous as they face the wrath of their families and communities.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80035480, 'After a freak explosion wreaks havoc on a sprawling city of the future, eight survivors get caught up in the aftermath and its paranormal effects.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70136135, 'Set in 1960s New York City, this award-winning series takes a peek inside an ad agency during an era when the cutthroat business had a glamorous lure.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80023794, 'This documentary explores the connections between elite athletes and Marvel superheroes such as Spider Man, Black Widow and Captain America.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70230417, 'Plucky lizard Oscar spends his time trying to avoid the hazards of the desert, including marauding chickens and bumbling adversaries.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80038296, 'Stand-up comedian and TV star Aziz Ansari ("Parks and Recreation") delivers his sharp-witted take on immigrants, relationships and the food industry.');
