INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70264616, 'R.L. Stine''s tales take on a life of their own in a series that combines original stories with adaptations drawn from the popular books.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70264612, 'Join Ms. Frizzle as the Magic School Bus travels to outer space, under the sea, through an anthill – and even inside the human body!');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80004534, '"Brooklyn Nine-Nine" star Chelsea Peretti showcases her diverse talents in this dark yet silly reimagining of the comedy special.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (80009431, 'The Oscar-nominated true story of the rangers risking their lives to save Africa''s most precious national park and its endangered gorillas.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70299286, 'The courageous investigators of Human Rights Watch''s Emergencies Team risk their lives to document unlawful attacks on civilians by brutal dictators.');
