INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70288423, 'Inspired by the variety shows of the 1970s, "A Russell Peters Christmas" is a sweet, silly, sentimental and, most of all, funny Christmas special.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70290568, '"Parks and Recreation" star Aziz Ansari takes the stage to share his unfiltered views on adulthood, babies, marriage, love and more in the modern era.');
