INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70280748, 'Global comedy star Russell Peters leaves no ethnic or cultural stereotype unsatirized in this outrageous standup appearance in Sydney, Australia.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70143811, 'A group of hyperprivileged Manhattan private-school kids seem to get away with everything. Except an anonymous blogger is watching their every move.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70278877, '"Last Comic Standing" winner Iliza Shlesinger unleashes her acerbic, stream-of-conscious comedy on an unsuspecting audience in her hometown of Dallas.');
