INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70253397, 'As preparations for the Winter Feast build, Po is caught between his obligations as the Dragon Warrior and his family holiday traditions.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70213466, 'Will Ferrell stars as a Spanish-speaking cowboy in this comedy about a Mexican clan trying to rescue their ranch from greedy creditors.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70258566, 'The Shrek characters parody the music video "Thriller"; B.O.B. and pals battle zombie carrots; and Megamind faces the effects of the Button of Doom.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70242630, 'Shrek celebrates Halloween, Puss in Boots is captured by soldiers, and the gang participates in a kingdom-wide singing competition.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70242629, 'In this set of shorts, Hiccup and the gang learn about different species of dragons. Then, Gobber goes in search of the Boneknapper Dragon.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (60003082, 'Two war buddies fall for two sisters and follow the girls to a resort owned by their former commanding officer, who is in danger of losing the place.');
