INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70206821, 'After reckless teens kill an Amish child, a prosecutor attempts to bring the youths to justice despite the condemnation he faces from the community.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70206816, 'After their child was abducted and murdered, John and Reve Walsh fought to raise national awareness of the problem of missing children.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (60022914, 'This drama based on real-life events tells the story of George McKenna, the tough, determined new principal of a notorious Los Angeles high school.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70206818, 'A lawyer''s husband is having an affair. When his mistress is found dead, he becomes the prime suspect – and his wife must take charge of his defense.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70206819, 'When high school football coach Charlie Wedemeyer is diagnosed with Lou Gehrig''s disease, he perseveres in leading his team despite becoming disabled.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70206822, 'When their college-age daughter suddenly begins acting erratically and is diagnosed with schizophrenia, a desperate couple seeks treatment for her.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70206820, 'After contracting HIV from a tainted blood treatment, teenaged hemophiliac Ryan White is forced to fight for his right to attend public school.');
