INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70206825, 'Laurie and Joseph are doctors who interview sexually abused children. With a lot of energy they track down a pedophile who has abused many toddlers.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70206826, 'A beauty pageant winner is stalked by a serial killer who kidnaps her sister and torments her family in this thriller based on a shocking true story.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (60003155, 'With his gift of dream interpretation and his brilliantly colored coat, Joseph inspires jealousy in his brothers in this animated Bible story.');
INSERT INTO MOVIE_DESCRIPTIONS (show_id, description) VALUES (70154110, 'While making a film about the incursion of Christopher Columbus in the New World, a director finds the Bolivian locals protesting modern exploitation.');
