DROP DATABASE IF EXISTS netflix_database;

CREATE DATABASE netflix_database;

USE netflix_database;

CREATE TABLE CAST (
    cast_id INT PRIMARY KEY,
    cast_members VARCHAR(255) 
);




CREATE TABLE DIRECTOR (
    director_id INT PRIMARY KEY,
    director_name VARCHAR(255) 
);


CREATE TABLE CASTING (
    id INT AUTO_INCREMENT PRIMARY KEY,
    show_id INT,
    cast_id INT,
    director_id INT,
    FOREIGN KEY (cast_id) REFERENCES `CAST`(cast_id),
    FOREIGN KEY (director_id) REFERENCES DIRECTOR(director_id)
);




CREATE TABLE LISTED_IN (
    listed_id INT PRIMARY KEY,
    listed_name VARCHAR(255)
);




CREATE TABLE DATA_LISTED_IN (
    show_id INT PRIMARY KEY,
    listed_id INT,
    FOREIGN KEY (listed_id) REFERENCES LISTED_IN(listed_id)
);




CREATE TABLE MISC (
    show_id INT PRIMARY KEY,
    type_name VARCHAR(255),
    country_name VARCHAR(255)
);



CREATE TABLE MOVIE_DESCRIPTIONS (
    show_id INT PRIMARY KEY,
    description TEXT NOT NULL
);

