CREATE TABLE MOVIE_INFO (
    show_id INT,
    listed_id INT,
    duration VARCHAR(255),
    PRIMARY KEY (show_id, listed_id),
    FOREIGN KEY (listed_id) REFERENCES LISTED_IN(listed_id)
);



CREATE TABLE MOVIES (
    show_id INT PRIMARY KEY,
    title VARCHAR(255)
);

