CREATE TABLE RATING (
    rating_id INT PRIMARY KEY,
    rating_description VARCHAR(255) NOT NULL
);




CREATE TABLE TIME_INFO (
    show_id INT PRIMARY KEY,
    date_added DATE,
    release_year INT
);




CREATE TABLE DATA_RATING (
    show_id INT PRIMARY KEY,
    rating_id INT,
    FOREIGN KEY (rating_id) REFERENCES RATING(rating_id)
);

